---@field TargetInfoCell                    UnityEngine.RectTransform
local UIBattlingTrainingTargetCell = Class('UIBattlingTrainingTargetCell')

------------ LifeCycle ------------

function UIBattlingTrainingTargetCell:__init()
    self:CleanField()
end

function UIBattlingTrainingTargetCell:__delete()
    self:CleanField()
end

function UIBattlingTrainingTargetCell:CleanField()
    self.listTargetNode = nil
    self.group = nil
    self.isInit = nil
    self.isFinish = nil
    self.showType = nil
end

function UIBattlingTrainingTargetCell:Awake()
    self.listTargetNode = {}
    self.group = 0
    self.isInit = false
    self.isFinish = false
end

function UIBattlingTrainingTargetCell:Start()
end

function UIBattlingTrainingTargetCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

------------ LifeCycle ------------

function UIBattlingTrainingTargetCell:CheckElementInList(id)
    for i, node in pairs(self.listTargetNode) do
        local _id = node:GetTypeId()
        if id == _id then
            return true
        end
    end
    return false
end

function UIBattlingTrainingTargetCell:GetListTargetNode()
    return self.listTargetNode
end

function UIBattlingTrainingTargetCell:UpdateCell(type, value, state)
    local finishId
    for i = 1, #self.listTargetNode do
        local node = self.listTargetNode[i]
        local typeId = node.taskId
        if type == typeId then
            --local isFinish = 
            node:SetMissionProcess(value, state)
            local isFinish = (state == Constants.BattleConditionState.Succeed)
            if isFinish then 
                finishId = typeId 
                break
            end
        end
    end
    ---或条件已完成一条就清理当前条件槽
    if finishId and finishId > 0 then
        self.isFinish = true
        for i = #self.listTargetNode, 1, -1 do
            local node = self.listTargetNode[i]
            local typeId = node.taskId
            if finishId ~= typeId then
                KTool.SetActive(node.controller.gameObject, false)
                table.remove(self.listTargetNode, i)
            end
        end
        KTool.SetActive(self.OrText.gameObject, false)
    end
    return finishId and finishId > 0
end

function UIBattlingTrainingTargetCell:InitTargetNode(data)
    local goNode = GameObject.Instantiate(self.TargetInfoCell.gameObject, self.controller.transform)
    if goNode then
        KTool.SetActive(goNode, true)
        local lbNodeMissionDesc = GetLuaBehaviour(goNode, Constants.UIBattlingLuaTablePath.UIBattlingTrainingTargetNode)
        lbNodeMissionDesc:Init()
        local ltNode = lbNodeMissionDesc.Env
        ltNode:InitData(data)
        if isNull(self.listTargetNode) then
            self.listTargetNode = {}
        end
        table.insert(self.listTargetNode, ltNode)
    end
end

function UIBattlingTrainingTargetCell:UpdateCondition(data)
    if not self.isInit then
        self.group = data.group
        self.isInit = true
    end
    self.showType = checkNumber(data.showType)
    self:InitTargetNode(data)
    local isShowTxtOr = self.listTargetNode and #self.listTargetNode > 1
    KTool.SetActive(self.OrText.gameObject,isShowTxtOr)
end

return UIBattlingTrainingTargetCell